INCLUDE PERFETTO MODULE slices.with_context;
CREATE PERFETTO TABLE cand_dev AS
SELECT *,CAST(EXTRACT_ARG(arg_set_id,'args.stream') AS INT) stream,
CASE WHEN category='gpu_memcpy' THEN 'copy' WHEN category='gpu_memset' THEN 'memset'
WHEN name GLOB '*ag_nvl*' OR name GLOB '*rs_nvl*' OR lower(name) GLOB '*deep_ep*' OR lower(name) GLOB '*deepep*' THEN 'ep'
WHEN lower(name) GLOB '*nccl*' THEN 'nccl' ELSE 'compute' END family
FROM thread_slice WHERE category IN ('kernel','gpu_memcpy','gpu_memset');
CREATE PERFETTO TABLE cand_link AS
SELECT d.*,h.id host_id,h.ts host_ts,h.dur host_dur,h.name host_name,h.tid host_tid
FROM cand_dev d JOIN flow f ON f.slice_in=d.id JOIN thread_slice h ON h.id=f.slice_out;
SELECT category,count(*) n,round(sum(dur)/1e6,3) sum_ms FROM thread_slice GROUP BY category ORDER BY n DESC;

CREATE PERFETTO TABLE cand_mb AS
WITH m AS (SELECT ROW_NUMBER() OVER(ORDER BY ts) mb,id,ts,ts+dur cpu_end FROM thread_slice WHERE category='user_annotation' AND name GLOB 'task.profile_update.*.microbatch.rank0')
SELECT *, (SELECT max(ts+dur) FROM cand_link d WHERE d.host_ts>=m.ts AND d.host_ts<m.cpu_end) device_end FROM m;
CREATE PERFETTO TABLE cand_win AS SELECT min(ts) lo,max(device_end) hi FROM cand_mb;
CREATE PERFETTO TABLE cand_events AS SELECT d.*,MAX(d.ts,w.lo) b,MIN(d.ts+d.dur,w.hi) e FROM cand_dev d JOIN cand_win w ON d.ts<w.hi AND d.ts+d.dur>w.lo;
CREATE PERFETTO TABLE cand_gaps AS
WITH p AS (SELECT *,MAX(e) OVER(ORDER BY b,e,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prev_end FROM cand_events)
SELECT *,b-prev_end gap FROM p WHERE b>prev_end;
SELECT mb,id,round((ts-(SELECT lo FROM cand_win))/1e6,3) start_ms,round((cpu_end-ts)/1e6,3) host_span_ms,round((device_end-ts)/1e6,3) through_device_ms FROM cand_mb;

