WITH c AS(SELECT id,ts,ts+dur e FROM thread_slice WHERE name='torchtitan::conditional_capacity_mask'),
s AS(SELECT h.id,h.ts,h.ts+h.dur e FROM thread_slice h JOIN c ON h.ts>=c.ts AND h.ts+h.dur<=c.e WHERE h.category='cuda_runtime' AND h.name='cudaStreamSynchronize')
SELECT (SELECT count(*) FROM c) capacity_calls,count(*) sync_calls,round(sum(e-ts)/1e6,3) host_sync_ms,round((SELECT sum(MIN(s.e,g.b)-MAX(s.ts,g.prev_end)) FROM s JOIN cand_gaps g ON s.ts<g.b AND s.e>g.prev_end)/1e6,3) sync_intersection_all_device_idle_ms FROM s;

